package main

import "fmt"

func Reverse(s []int) []int {
  for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
    s[i], s[j] = s[j], s[i]
  }
  return s
}

func main() {
  fmt.Println(Reverse([]int{1, 2, 3, 4, 5}))
}

