questions.referenceSolution:
package main

import "fmt"

func Filter[T any](s []T, pred func(T) bool) []T {
  out := []T{}
  for _, v := range s {
    if pred(v) {
      out = append(out, v)
    }
  }
  return out
}

func main() {
  evens := Filter([]int{1, 2, 3, 4, 5, 6}, func(n int) bool { return n%2 == 0 })
  fmt.Println(evens)
}
